    "author": "胡璐",
    "description": "务农重本，国之大纲。 8月28日，十四届全国人大常委会第二十四次会议表决通过新修订的农业法，自2027年1月1日起施行。 为何要大修农业法？ 农业法是农业和农村经济领域的基础性法律，于1993年制定，2002年进行了全面修改，2009年和2012年分别对个别条款作了修改。新时代新征程，农业农村经济发展面临新形势新任务。推进乡村全面振兴，加快建设农业强国，有必要修改这部法律。 ——实施国家粮食安全战略，更好端牢中国饭碗。 农业强，首要是粮…",
    "content": "务农重本，国之大纲。 8月28日，十四届全国人大常委会第二十四次会议表决通过新修订的农业法，自2027年1月1日起施行。 为何要大修农业法？ 农业法是农业和农村经济领域的基础性法律，于1993年制定，2002年进行了全面修改，2009年和2012年分别对个别条款作了修改。新时代新征程，农业农村经济发展面临新形势新任务。推进乡村全面振兴，加快建设农业强国，有必要修改这部法律。 —— 实施国家粮食安全战略，更好端牢中国饭碗。 农业强，首要是粮食和重要农产品供给保障能力必须强。 近年来，我国粮食生产连年丰收，粮食产量连续…"
