    "content": "中新社沈阳8月28日电 (姜月恒)“勿忘九一八 传承抗战精神”暨纪念九一八事变爆发95周年活动28日在沈阳举行。活动回顾两岸同胞共御外侮的峥嵘岁月，深挖抗战精神所蕴含的两岸共同精神内核，“台盟爱国主义教育基地”在沈阳“九·一八”历史博物馆揭牌。"
