    "content": "8月26日上午10时30分许 一场从尼泊尔境内 海拔5200米冰川启动的灾害 仅用约7分钟就沿着20多公里河谷 冲向中国吉隆口岸 这是一条“冰崩—碎屑流—泥石流” 层层放大的灾害链 一条视频 带你看懂这次泥石流何以发生 ↓↓↓ 自然资源部有关专家表示，此次灾害由尼泊尔境内高位冰川崩塌引发。 专家解释说，冰崩落体高速下泄，沿沟道裹挟冰碛物演变为碎屑流，进而汇入东林藏布形成泥石流，冲击吉隆口岸并向下游尼泊尔方向运动。 “这次灾害的成因是冰崩引发的碎屑流。具体来说，高位冰崩从山坡上垮落下来，高速运动过程中铲刮了沟道里的冰…"
