    "description": "新华社北京8月28日电（记者张千千）中国工商银行8月28日公布的2026年半年度报告显示，上半年，工商银行贷款投放、债券投资增量超3万亿元，其中境内分行人民币贷款增加1.43万亿元，人民币债券投资增加1.58万亿元。 据介绍，工商银行积极服务制造业智能化、绿色化、融合化发展，加力支持“两重”建设、“两新”工作及科技自立自强、普惠、民营、城市更新等重点领域。截至今年6月末，工行投向制造业贷款余额超5.8万亿元，普惠贷款余额超3.9万亿元，…",
    "content": "新华社北京8月28日电（记者张千千）中国工商银行8月28日公布的2026年半年度报告显示，上半年，工商银行贷款投放、债券投资增量超3万亿元，其中境内分行人民币贷款增加1.43万亿元，人民币债券投资增加1.58万亿元。 据介绍，工商银行积极服务制造业智能化、绿色化、融合化发展，加力支持“两重”建设、“两新”工作及科技自立自强、普惠、民营、城市更新等重点领域。截至今年6月末，工行投向制造业贷款余额超5.8万亿元，普惠贷款余额超3.9万亿元，绿色贷款余额超7万亿元。 数据显示，工商银行扎实推进乡村全面振兴，截至6月末，涉…"
