    "author": "王晓梅,王雷",
    "description": "新华社开普敦8月28日电（记者王晓梅 王雷）南非国家电力公司27日晚间发布声明说，该国库贝赫核电站1号机组当天凌晨在出现汽轮机跳闸后按照既定程序安全停机。这意味着该核电站暂时处于完全停运状态。 声明说，库贝赫核电站1号机组暂停向电网供电不会对南非全国电力供应构成风险，电网运行依然安全稳定。事件未对核安全造成影响，也未对员工、公众和环境构成风险。汽轮机跳闸的原因正在调查中。 库贝赫核电站位于南非西海岸，距离开普敦约27公里，是非洲唯一在运…",
    "content": "新华社开普敦8月28日电（记者王晓梅 王雷）南非国家电力公司27日晚间发布声明说，该国库贝赫核电站1号机组当天凌晨在出现汽轮机跳闸后按照既定程序安全停机。这意味着该核电站暂时处于完全停运状态。 声明说，库贝赫核电站1号机组暂停向电网供电不会对南非全国电力供应构成风险，电网运行依然安全稳定。事件未对核安全造成影响，也未对员工、公众和环境构成风险。汽轮机跳闸的原因正在调查中。 库贝赫核电站位于南非西海岸，距离开普敦约27公里，是非洲唯一在运核电站。该核电站于20世纪80年代建成投运，两台机组的总装机容量约1800兆瓦。…"
