    "content": "（本文首发于南方人物周刊） 南方人物周刊记者 张宇欣 责任编辑：李屾淼 （受访者提供/图） 相关报道详见《 文昕：成为影帝的那一刻，很多人才第一次听说他的名字 》 拿到第20届FIRST最佳演员荣誉以后，演员文昕主动通知的人很少，“郭总”是其中一个。 几年前，文昕参加陈坤组织的“行走的力量”徒步。那时他在四川老家开着自己的健身房，三次申请山下学堂都没中，几乎打算放弃演艺行业了。在徒步路上，文昕认识了一个他称为郭总的朋友，跟对方讲了自己想当演员而不得的故事。对方说，文昕啊，你知道我们为什么在这里相见吗？因为你心里那团…"
