    "author": "刘杨,张平",
    "description": "新华社加德满都8月28日电（记者刘杨 张平）尼泊尔国家减少灾害风险管理局28日在社交媒体上发文称，截至当地时间19时，该国山洪引发的泥石流已导致579人遇难，另有1924人失联。",
    "content": "新华社加德满都8月28日电（记者刘杨 张平）尼泊尔国家减少灾害风险管理局28日在社交媒体上发文称，截至当地时间19时，该国山洪引发的泥石流已导致579人遇难，另有1924人失联。"
