    "title": "四川省人大监察和司法委员会原主任委员郑东风受贿案一审宣判",
    "link": "http://www.news.cn/20260828/5056668288684b6192276193cea4fda0/c.html",
    "pub_date": "2026-08-28 22:36:08",
    "author": "唐文豪",
    "description": "新华社成都8月28日电（记者唐文豪）8月28日，四川省自贡市中级人民法院一审公开宣判四川省人大监察和司法委员会原主任委员郑东风受贿案，对被告人郑东风以受贿罪判处有期徒刑十五年，并处罚金人民币六百万元；对追缴在案的郑东风受贿所得财物依法上缴国库，不足部分继续追缴。 经审理查明：2008年至2024年，被告人郑东风利用担任四川省纪委常委、副书记，四川省监察委员会副主任等职务上的便利，为他人在工程项目承揽及推进、职工录用及岗位调整、医药配送及…",
    "content": "新华社成都8月28日电（记者唐文豪）8月28日，四川省自贡市中级人民法院一审公开宣判四川省人大监察和司法委员会原主任委员郑东风受贿案，对被告人郑东风以受贿罪判处有期徒刑十五年，并处罚金人民币六百万元；对追缴在案的郑东风受贿所得财物依法上缴国库，不足部分继续追缴。 经审理查明：2008年至2024年，被告人郑东风利用担任四川省纪委常委、副书记，四川省监察委员会副主任等职务上的便利，为他人在工程项目承揽及推进、职工录用及岗位调整、医药配送及医疗设备采购等事项上提供帮助，非法收受财物共计折合人民币8161万余元，其中部分…"
