    "title": "日本陆上自卫队将强闯中国使馆的村田晃大免职",
    "link": "http://www.news.cn/20260828/7e35c360c198473ab9ef8a381f915723/c.html",
    "pub_date": "2026-08-28 22:36:04",
    "author": "陈泽安,梁晨",
    "description": "新华社东京8月28日电（记者陈泽安 梁晨）据日本共同社报道，日本陆上自卫队28日对强闯中国驻日本大使馆的三等陆尉村田晃大作出免职处分。 今年3月24日，村田晃大携刀翻墙强行闯入中国驻日本大使馆，威胁杀害中国外交人员，随后被警方逮捕。日本检方以入侵建筑物、威胁使馆工作人员等罪名对其提起公诉。 中国驻日使馆就闯馆事件提出严正交涉并表示强烈抗议，要求日方作出负责任的交代。然而，日方仅表示“遗憾”，并未道歉。",
    "content": "新华社东京8月28日电（记者陈泽安 梁晨）据日本共同社报道，日本陆上自卫队28日对强闯中国驻日本大使馆的三等陆尉村田晃大作出免职处分。 今年3月24日，村田晃大携刀翻墙强行闯入中国驻日本大使馆，威胁杀害中国外交人员，随后被警方逮捕。日本检方以入侵建筑物、威胁使馆工作人员等罪名对其提起公诉。 中国驻日使馆就闯馆事件提出严正交涉并表示强烈抗议，要求日方作出负责任的交代。然而，日方仅表示“遗憾”，并未道歉。"
