    "content": "新华社北京8月28日电 题：构建房地产发展新模式，信贷管理这样改革完善 新华社记者吴雨 8月28日，中国人民银行、国家金融监督管理总局联合印发《关于改革完善房地产信贷管理 推动加快构建房地产发展新模式的意见》，对房地产贷款制度进行优化，构建全面覆盖、有序衔接的房地产信贷产品体系，以更好满足房地产发展新模式合理融资需求。 为何对现有制度进行改革完善？ 我国形成商品房预售制度以来，逐渐建立了配套的房地产信贷制度，有效满足了房地产市场起步和增长阶段的融资需求。但在市场长期发展过程中，也积累暴露出一些问题，需要改革传统发展…"
