    "content": "新华社成都8月28日电（记者童芳、杨进）28日四川省内江市隆昌市发生5.1级地震，21时40分许，四川省隆昌市应对地震防灾救灾工作领导小组办公室通报地震情况，地震发生后隆昌市第一时间启动应急响应，经全域全面摸排隐患，截至目前暂未发现人员伤亡、房屋倒塌等情况。隆昌市电力、通信、燃气、供水和交通等秩序正常。 记者28日18时许在震中的胡家镇元嘴村走访看到，房屋整体未见明显损伤，部分旧房的外墙和内部可见轻微裂纹，屋檐下散落着少量被震落的瓦片。村民彭文琴和邻居说，地震发生时大家迅速跑到院坝避险，摇晃了大概十秒。当地干部介绍…"
