    "author": "澎湃新闻记者 罗昕 实习生 郑博文",
    "description": "今夜的上海，因文学的炬火而格外明亮。 在鲁迅先生诞辰145周年、逝世90周年之际，鲁迅文学奖颁奖典礼首次来到上海——这座鲁迅先生曾长期生活、写作的城市。8月28日晚，由中国作家协会和上海市人民政府共同主办的“中国文学盛典·鲁迅文学奖之夜”在沪璀璨登场。 鲁迅文学奖创立于1997年，是代表我国最高荣誉的国家级文学奖之一，每四年评选一次。第九届鲁迅文学奖于7月15日揭晓，中篇小说奖、短篇小说奖、报告文学奖、诗歌奖、散文杂文奖、文学理论评论奖…",
