    "content": "新华社莫斯科8月28日电（记者许炜凯 乌里扬娜）中国国际大学生创新大赛（2026）俄罗斯区域赛决赛27日在莫斯科举行。 本次赛事是中国国际大学生创新大赛首次举办俄罗斯区域赛，吸引来自俄罗斯、白俄罗斯等国102所高校的518支青年创新创业团队参赛。莫斯科鲍曼国立技术大学的“极地移动清洁能源平台”等项目从晋级决赛的50个项目中脱颖而出，斩获金奖。 中国驻俄罗斯大使馆公使衔参赞曹士海在赛后举行的颁奖典礼上致辞表示，本次赛事有500余支队伍参与，充分体现了青年群体对创新创业的浓厚兴趣，相信本次活动将进一步促进中俄高校开展创…"
