    "author": "魏玉坤",
    "description": "新华社北京8月28日电 记者28日从国家发展改革委获悉，国家发展改革委紧急安排中央预算内投资1亿元，支持浙江、福建做好台风灾害灾后应急恢复，重点用于灾区受损道路、水利等基础设施和学校、医院等公共服务设施灾后应急恢复建设，推动尽快恢复正常生产生活秩序。 8月28日早晨，今年第18号台风“沙德尔”先后在浙江台州玉环市、温州龙湾区沿海登陆。当日，国家防减救灾委、应急管理部针对本次台风对浙江、福建造成的严重影响，启动国家四级救灾应急响应。",
