    "title": "观天下丨伊朗战事的六大影响",
    "link": "http://www.news.cn/20260828/bb909e75ee7d4cbfab2dfbd3814449ef/c.html",
    "pub_date": "2026-08-28 22:12:27",
    "author": "陈立希",
    "description": "新华社北京8月28日电 自美国和以色列2月28日对伊朗发起军事行动以来，伊朗战事已延宕半年。如今，美伊谈判陷于停滞，美方扬言将用一切手段使其“经济孤立”，同时“保留所有选项”；伊朗则强调国家韧性，保持非对称作战能力，并持续管控霍尔木兹海峡。 这场战事对美伊以三国、中东地区乃至全球都产生影响。据外媒总结，影响至少包括以下六方面。 政治代价不容忽视 据路透社和益普索集团日前发布的联合民调，仅约三成美国人支持美国对伊朗战事，为战事爆发以来最低…",
    "content": "新华社北京8月28日电 自美国和以色列2月28日对伊朗发起军事行动以来，伊朗战事已延宕半年。如今，美伊谈判陷于停滞，美方扬言将用一切手段使其“经济孤立”，同时“保留所有选项”；伊朗则强调国家韧性，保持非对称作战能力，并持续管控霍尔木兹海峡。 这场战事对美伊以三国、中东地区乃至全球都产生影响。据外媒总结，影响至少包括以下六方面。 政治代价不容忽视 据路透社和益普索集团日前发布的联合民调，仅约三成美国人支持美国对伊朗战事，为战事爆发以来最低水平。受此影响，美国总统特朗普的支持率也跌至33%的历史新低。 英国《经济学人》…"
