    "author": "洛卓嘉措,董博涵,陶冶,洛登",
    "description": "8月26日，因尼泊尔一侧发生泥石流灾害，造成西藏日喀则市吉隆县吉隆口岸重大人员伤亡、失联。28日，在西藏日喀则吉隆镇，多方救援保障力量全力开展抢险救灾与民生保障工作。 记者在吉隆镇看到，携带各类装备的救援力量不断汇集，救援侦测紧张开展，现场通信、物资保障工作有序推进。 记者：董博涵、洛卓嘉措、陶冶、洛登 编导：房宽 新华社音视频部制作",
    "content": "8月26日，因尼泊尔一侧发生泥石流灾害，造成西藏日喀则市吉隆县吉隆口岸重大人员伤亡、失联。28日，在西藏日喀则吉隆镇，多方救援保障力量全力开展抢险救灾与民生保障工作。 记者在吉隆镇看到，携带各类装备的救援力量不断汇集，救援侦测紧张开展，现场通信、物资保障工作有序推进。 记者：董博涵、洛卓嘉措、陶冶、洛登 编导：房宽 新华社音视频部制作"
