    "description": "“我骑着雄鹰，飞过千层云、万重山；我骑着天鹅，飞过千条河、万条江；我要去寻找木竹林莫日根，把他的故事传唱……”悠远的赫哲族伊玛堪，传唱着古老的民族故事，也诉说着赫哲儿女守边兴边的时代新貌。 赫哲族被称为“守望太阳的民族”。黑龙江省抚远市居民尤军介绍，天未破晓，赫哲族群众便下江捕鱼，看着第一缕阳光遍洒祖国大地，世代守护着祖国东部边境。 70余年来，赫哲族完成了从渔猎游牧到农耕定居的历史跨越，群众的生活居所、生活质量发生了翻天覆地的变化。 …",
    "content": "“我骑着雄鹰，飞过千层云、万重山；我骑着天鹅，飞过千条河、万条江；我要去寻找木竹林莫日根，把他的故事传唱……”悠远的赫哲族伊玛堪，传唱着古老的民族故事，也诉说着赫哲儿女守边兴边的时代新貌。 赫哲族被称为“守望太阳的民族”。黑龙江省抚远市居民尤军介绍，天未破晓，赫哲族群众便下江捕鱼，看着第一缕阳光遍洒祖国大地，世代守护着祖国东部边境。 70余年来，赫哲族完成了从渔猎游牧到农耕定居的历史跨越，群众的生活居所、生活质量发生了翻天覆地的变化。 依托独特的边境风光和民俗资源，在各级政府的大力扶持下，当地文旅民宿产业蓬勃兴起，…"
