    "content": "新华社北京8月28日电 全国人民代表大会常务委员会关于修改《中华人民共和国律师法》的决定 （2026年8月28日第十四届全国人民代表大会常务委员会第二十四次会议通过） 第十四届全国人民代表大会常务委员会第二十四次会议决定对《中华人民共和国律师法》作如下修改： 一、将第一条中的“发挥律师在社会主义法制建设中的作用”修改为“发挥律师在社会主义法治建设中的作用”，“制定本法”修改为“根据宪法，制定本法”。 二、增加一条，作为第三条：“律师工作坚持中国共产党的领导，贯彻落实党和国家路线方针政策、决策部署，服务中国式现代化建…"
