    "title": "房地产融资迎来五项新规：个人住房贷款最长可达40年，预售房贷竣工备案后发放",
    "link": "https://m.thepaper.cn/detail/33968936",
    "pub_date": "2026-08-28 21:30:12",
    "author": "澎湃新闻记者 胡志挺",
    "description": "8月28日，国家金融监督管理总局会同中国人民银行、住房城乡建设部等部门发布五项房地产融资管理制度，涉及商品住房开发贷款、个人住房贷款、商业地产贷款、城市更新项目贷款以及房地产领域信托业务。 此次发布的五项制度分别为《商品住房开发贷款管理办法（试行）》《个人住房贷款管理办法（试行）》《商业地产贷款管理办法（试行）》《城市更新项目贷款管理办法（试行）》《信托公司开展房地产领域信托业务管理办法（试行）》。 金融监管总局表示，此次在全面梳理房地…",
    "content": "8月28日，国家金融监督管理总局会同中国人民银行、住房城乡建设部等部门发布五项房地产融资管理制度，涉及商品住房开发贷款、个人住房贷款、商业地产贷款、城市更新项目贷款以及房地产领域信托业务。 此次发布的五项制度分别为《商品住房开发贷款管理办法（试行）》《个人住房贷款管理办法（试行）》《商业地产贷款管理办法（试行）》《城市更新项目贷款管理办法（试行）》《信托公司开展房地产领域信托业务管理办法（试行）》。 金融监管总局表示，此次在全面梳理房地产金融领域现有政策的基础上，立足房地产市场形势和未来发展方向，与相关制度有序衔接…"
