    "description": "新华社北京8月28日电 题：规范完善政策 限售股解禁后的送转股将征收个税 新华社记者申铖 8月28日，财政部、税务总局、中国证监会对外发布公告，规范限售股个人所得税政策。根据公告，自8月28日起，限售股解禁后的送转股将纳入个税征税范围。 为支持资本市场发展，我国自1994年起对个人转让境内上市公司股票暂免征收个税。随着资本市场不断发展，我国自2010年起对个人转让限售股按20%税率征收个税，并将首次公开发行股票并上市的公司形成的限售股，…",
    "content": "新华社北京8月28日电 题：规范完善政策 限售股解禁后的送转股将征收个税 新华社记者申铖 8月28日，财政部、税务总局、中国证监会对外发布公告，规范限售股个人所得税政策。根据公告，自8月28日起，限售股解禁后的送转股将纳入个税征税范围。 为支持资本市场发展，我国自1994年起对个人转让境内上市公司股票暂免征收个税。随着资本市场不断发展，我国自2010年起对个人转让限售股按20%税率征收个税，并将首次公开发行股票并上市的公司形成的限售股，及上述股份解禁前的送转股，均纳入征税范围。 北京国家会计学院副院长李旭红表示，此…"
