    "description": "新华社北京8月28日电（记者吴雨）8月28日，中国人民银行、国家金融监督管理总局联合印发《关于改革完善房地产信贷管理 推动加快构建房地产发展新模式的意见》，优化房地产信贷体系，更好满足房地产合理信贷需求，维护购房人合法权益，促进金融与房地产良性循环。 意见共36条，既是商品住房销售制度改革的配套制度，也是完善房地产基础制度的重要组成部分。 意见围绕房地产开发、建设、销售、运营全生命周期的信贷需求，明确商品住房、保障性住房、租赁住房、商业…",
    "content": "新华社北京8月28日电（记者吴雨）8月28日，中国人民银行、国家金融监督管理总局联合印发《关于改革完善房地产信贷管理 推动加快构建房地产发展新模式的意见》，优化房地产信贷体系，更好满足房地产合理信贷需求，维护购房人合法权益，促进金融与房地产良性循环。 意见共36条，既是商品住房销售制度改革的配套制度，也是完善房地产基础制度的重要组成部分。 意见围绕房地产开发、建设、销售、运营全生命周期的信贷需求，明确商品住房、保障性住房、租赁住房、商业地产等细分领域的贷款品种，加强各品种间的衔接，统筹规划贷款对象、期限、用途、抵押…"
