    "content": "新华社北京8月28日电（记者刘羽佳、刘慧）记者8月28日从中国证监会获悉，为加快构建与房地产发展新模式相匹配的资本市场服务体系，服务住房品质提升和企业转型发展，促进金融与房地产良性循环，证监会制定了《关于资本市场支持构建房地产发展新模式的意见》，于28日对外发布。 此次发布的意见主要包括支持合理融资、优化监管、防范化解风险等内容。 围绕支持合理融资，意见明确，支持上市房地产开发企业再融资以及综合运用发行股份、定向可转债、现金等工具收购涉房资产。加大债券融资支持力度，支持房地产开发企业发行公司债券用于符合政策要求的房…"
