    "pub_date": "2026-08-28 19:52:01",
    "author": "黄垚",
    "description": "新华社北京8月28日电 题：五部门联合发文 促进构建生态环境科技多元投入格局 新华社记者黄垚、高敬 记者28日从生态环境部获悉，生态环境部等五部门近日联合印发《关于推动生态环境领域科技创新多元化投入的指导意见》，加快构建多主体参与、多渠道保障、全链条衔接的生态环境领域科技创新多元化投入格局，提升生态环境领域科技创新供给能力和产业化水平，为美丽中国建设提供有力科技支撑。 “近年来，我国生态环境科技创新能力持续提升，为深入打好污染防治攻坚战…",
    "content": "新华社北京8月28日电 题：五部门联合发文 促进构建生态环境科技多元投入格局 新华社记者黄垚、高敬 记者28日从生态环境部获悉，生态环境部等五部门近日联合印发《关于推动生态环境领域科技创新多元化投入的指导意见》，加快构建多主体参与、多渠道保障、全链条衔接的生态环境领域科技创新多元化投入格局，提升生态环境领域科技创新供给能力和产业化水平，为美丽中国建设提供有力科技支撑。 “近年来，我国生态环境科技创新能力持续提升，为深入打好污染防治攻坚战、全面推进美丽中国建设提供了有力支撑。”生态环境部科技与财务司有关负责人说，同时…"
