    "description": "新华社兰州/比什凯克8月28日电 心相近丨中吉共续文化丝路情缘 新华社记者张玉洁 朱瑞卿 江宥林 “2000多年前，中国汉代张骞远行西域，古丝绸之路逶迤穿过碎叶古城。”2019年6月访问吉尔吉斯斯坦前夕，习近平主席在当地媒体发表署名文章，回望两国源远流长的友好交往。 阿克-贝希姆遗址，也就是大家所熟知的碎叶古城遗址位于吉尔吉斯斯坦境内，是中国同吉尔吉斯斯坦、哈萨克斯坦成功联合申遗的“丝绸之路：长安-天山廊道的路网”中一处重要遗产点。 楚…",
    "content": "新华社兰州/比什凯克8月28日电 心相近丨中吉共续文化丝路情缘 新华社记者张玉洁 朱瑞卿 江宥林 “2000多年前，中国汉代张骞远行西域，古丝绸之路逶迤穿过碎叶古城。”2019年6月访问吉尔吉斯斯坦前夕，习近平主席在当地媒体发表署名文章，回望两国源远流长的友好交往。 阿克-贝希姆遗址，也就是大家所熟知的碎叶古城遗址位于吉尔吉斯斯坦境内，是中国同吉尔吉斯斯坦、哈萨克斯坦成功联合申遗的“丝绸之路：长安-天山廊道的路网”中一处重要遗产点。 楚河谷地的碎叶遗址，中吉文物工作者正并肩开展文物保护工作。大漠深处的敦煌，中吉等国…"
