    "description": "新华社北京8月28日电 近期，多个台风接连登陆我国，华东、华南等区域普降暴雨，引发严重险情灾情。8月28日，财政部、应急管理部紧急拨付1.5亿元中央自然灾害救灾资金，支持浙江、福建、广西等3省（区）开展防汛防台风应急抢险救灾工作，重点做好受灾群众转移安置、排危除险等应急处置、过渡期生活救助以及倒损民房修复等工作，切实减轻灾害损失，保障人民群众生命财产安全。",
    "content": "新华社北京8月28日电 近期，多个台风接连登陆我国，华东、华南等区域普降暴雨，引发严重险情灾情。8月28日，财政部、应急管理部紧急拨付1.5亿元中央自然灾害救灾资金，支持浙江、福建、广西等3省（区）开展防汛防台风应急抢险救灾工作，重点做好受灾群众转移安置、排危除险等应急处置、过渡期生活救助以及倒损民房修复等工作，切实减轻灾害损失，保障人民群众生命财产安全。"
